{"results": [{"id": "hp_doc_6610a8d99999373247199029cfd75ffac271e9b1d5e185f094d9fcb67ddc3d0f", "title": "Wilhelm Molterer", "text": "Wilhelm Molterer (born 14 May 1955 in Steyr) is Vice-President and member of the Management Committee of the European Investment Bank (EIB). Before joining the EIB, he was Member of the Austrian Parliament. He has been Vice Chancellor and Finance Minister of Austria and chairman of the conservative Austrian People's Party.", "score": 22.1573}, {"id": "hp_doc_41a5df070fa38ab007cde998ac6d1e2eb2499d28992fd68032f9936cc8217dcf", "title": "Mignon (Schubert)", "text": "Mignon, a character appearing in Johann Wolfgang von Goethe's writings such as \"Wilhelm Meister's Apprenticeship\" and \"Wilhelm Meister's Journeyman Years\", is the subject of several lieder by Franz Schubert.", "score": 9.3591}, {"id": "hp_doc_e1863558f35f9b7acd1722d83a8d20d9be236db1016fc0184a02dae0c43a3ea0", "title": "Wilhelm Wiegand", "text": "Wilhelm Wiegand (5 November 1851, Ellrich – 8 March 1915, Strasbourg) was a German archivist and historian. He is best known for his research of Alsatian history and his publications involving Frederick the Great.", "score": 9.2004}], "remaining_searches": 2}
